from wikilib import *

group("Start", "Start")


@page("wiki.html", "Overview", "Übersicht")
def _():
    body = SEC(
        H2("What LJ Link does", "Was LJ Link macht"),
        P("LJ Link shows the lighting jockey what the DJ is playing: every deck with waveform, cues, beat grid, time and tempo, live in the browser. On request it also sends the tempo to the light desk, so chasers and effects run in time with the music.",
          "LJ Link zeigt dem Lichtjockey, was der DJ spielt: jedes Deck mit Waveform, Cues, Beatgrid, Zeit und Tempo, live im Browser. Auf Wunsch schickt es auch das Tempo ans Lichtpult, damit Chaser und Effekte im Takt der Musik laufen."),
        UL(("**Passive:** LJ Link only listens. It never sends sync, tempo or fader commands to the DJ gear. One exception, off by default: the optional [Ableton Link output](wiki-ableton-link.html#send) leads the tempo of a Link session, so DJ software that joins it (such as Traktor) follows LJ Link’s tempo.",
            "**Passiv:** LJ Link hört nur zu. Es schickt nie Sync-, Tempo- oder Fader-Befehle an die DJ-Geräte. Einzige Ausnahme, standardmäßig aus: Der optionale [Ableton-Link-Ausgang](wiki-ableton-link.html#send) gibt einer Link-Session das Tempo vor, und DJ-Software, die ihr beitritt (etwa Traktor), folgt dem Tempo von LJ Link."),
           ("**Local:** no internet, no cloud, no account. Only the update check uses the internet.",
            "**Lokal:** kein Internet, keine Cloud, kein Konto. Nur die Update-Prüfung nutzt das Internet."),
           ("**Free and open source** for macOS and Windows.", "**Kostenlos und Open Source** für macOS und Windows.")),
        H2("Find your use case", "Finde deinen Anwendungsfall"),
        P("Pick the line that fits you best. Every use case page walks through the whole setup, from cables to the first beat on the desk.",
          "Such dir die Zeile aus, die am besten passt. Jede Seite zu einem Anwendungsfall geht den ganzen Aufbau durch, vom Kabel bis zum ersten Beat am Pult."),
        TABLE([("You have …", "Du hast …"), ("You want …", "Du willst …"), ("Read", "Lies")], [
            [("CDJs/XDJs and a DJM in a club, a grandMA2 at FOH", "CDJs/XDJs und ein DJM im Club, einen grandMA2 am FOH"), ("waveforms and the tempo on a speed master", "Waveforms und das Tempo auf einem Speedmaster"), ("[Club with CDJs and grandMA2](wiki-case-club.html)", "[Club mit CDJs und grandMA2](wiki-case-club.html)")],
            [("one laptop with grandMA2 or grandMA3 onPC", "einen Laptop mit grandMA2 oder grandMA3 onPC"), ("LJ Link and onPC on the same computer", "LJ Link und onPC auf demselben Computer"), ("[One laptop with onPC](wiki-case-onpc.html)", "[Ein Laptop mit onPC](wiki-case-onpc.html)")],
            [("several DJs with Pioneer and Denon in one night", "mehrere DJs mit Pioneer und Denon an einem Abend"), ("all decks in one view, tempo from whoever plays", "alle Decks in einer Ansicht, Tempo von dem, der spielt"), ("[Several DJs, mixed gear](wiki-case-mixed.html)", "[Mehrere DJs, gemischte Geräte](wiki-case-mixed.html)")],
            [("a Denon Prime and a Wolfmix", "einen Denon Prime und einen Wolfmix"), ("a small mobile setup", "einen kleinen mobilen Aufbau"), ("[Mobile setup with Denon and Wolfmix](wiki-case-mobile.html)", "[Mobil mit Denon und Wolfmix](wiki-case-mobile.html)")],
            [("a DJ who plays Serato DJ Pro", "einen DJ, der mit Serato DJ Pro spielt"), ("the loaded tracks and the tempo", "die geladenen Tracks und das Tempo"), ("[Serato on the DJ laptop](wiki-case-serato.html)", "[Serato auf dem DJ-Laptop](wiki-case-serato.html)")],
            [("a DJ with Serato DJ Pro on a Mac who does not want LJ Link on it", "einen DJ mit Serato DJ Pro auf dem Mac, der LJ Link dort nicht haben will"), ("the Serato decks with position in the booth (alpha)", "die Serato-Decks mit Position in der Booth (Alpha)"), ("[LJL Link](wiki-ljl-link.html)", "[LJL Link](wiki-ljl-link.html)")],
            [("no light desk link, just a tablet", "kein Pult-Link, nur ein Tablet"), ("to see the drops coming", "die Drops kommen sehen"), ("[Waveforms on a tablet](wiki-case-tablet.html)", "[Waveforms auf dem Tablet](wiki-case-tablet.html)")],
            [("a separate light network (MA-Net, Art-Net, sACN)", "ein eigenes Lichtnetz (MA-Net, Art-Net, sACN)"), ("to keep DJ and light networks apart", "DJ- und Lichtnetz getrennt halten"), ("[Two networks](wiki-case-two-networks.html)", "[Zwei Netzwerke](wiki-case-two-networks.html)")],
            [("only one cable and no switch", "nur ein Kabel und keinen Switch"), ("a quick setup", "einen schnellen Aufbau"), ("[Direct cable](wiki-case-direct.html)", "[Direktkabel](wiki-case-direct.html)")],
            [("a livestream or a photographer", "einen Livestream oder Fotografen"), ("no track titles on the screen", "keine Titel auf dem Bildschirm"), ("[Livestream and privacy mode](wiki-case-stream.html)", "[Livestream und Privatsphäre-Modus](wiki-case-stream.html)")],
        ]),
        H2("How this wiki is organised", "So ist das Wiki aufgebaut"),
        CARDS(("🚀", "wiki-quickstart.html", "Start", "Start", "Quick start, installation and a tour of the interface.", "Schnellstart, Installation und ein Rundgang durch die Oberfläche."),
              ("🔌", "wiki-network.html", "Network", "Netzwerk", "Cables, switch or router, Wi-Fi, IP addresses and ports. What works best.", "Kabel, Switch oder Router, WLAN, IP-Adressen und Ports. Was am besten funktioniert."),
              ("🎧", "wiki-sources.html", "DJ sources", "DJ-Quellen", "Pioneer, Denon, Serato and Ableton Link: what each one shows.", "Pioneer, Denon, Serato und Ableton Link: was jede Quelle zeigt."),
              ("🟧", "wiki-ljl-link.html", "LJL Link (alpha)", "LJL Link (Alpha)", "Serato DJ Pro decks from the DJ’s Mac in the booth, from the club’s USB stick.", "Serato-DJ-Pro-Decks vom Mac des DJs in der Booth, vom USB-Stick des Clubs."),
              ("💡", "wiki-lighting-desks.html", "Light desks", "Lichtpulte", "grandMA2, grandMA3, Wolfmix, Daslight and OSC programs, step by step.", "grandMA2, grandMA3, Wolfmix, Daslight und OSC-Programme, Schritt für Schritt."),
              ("🎛️", "wiki-use-cases.html", "Use cases", "Anwendungsfälle", "Complete setups for club, festival, mobile, livestream and more.", "Komplette Aufbauten für Club, Festival, mobil, Livestream und mehr."),
              ("🛟", "wiki-troubleshooting.html", "Help", "Hilfe", "Troubleshooting by symptom, known issues, glossary and reference.", "Fehlersuche nach Symptom, bekannte Fehler, Glossar und Referenz.")),
        H2("What the status means", "Was der Stand bedeutet"),
        P("Every device and program in this wiki carries one of these labels. We only call something stable when it ran on the real device. There is no formal test protocol: “works” means it ran with LJ Link in our own setups. Tell us how it runs in yours with a [hardware report](https://github.com/skyplayser/LJ-Link/issues/new?template=hardware-report.yml).",
          "Jedes Gerät und Programm in diesem Wiki trägt eines dieser Zeichen. Stabil nennen wir etwas nur, wenn es am echten Gerät lief. Ein formales Testprotokoll gibt es nicht: „läuft“ heißt, es lief in unseren eigenen Aufbauten mit LJ Link. Erzähl uns mit einem [Hardware-Bericht](https://github.com/skyplayser/LJ-Link/issues/new?template=hardware-report.yml), wie es bei dir läuft."),
        TABLE([("Status", "Stand"), ("Meaning", "Bedeutung")], [
            [BADGE("stable"), ("Ran on the real device in our own setup.", "Lief am echten Gerät in unserem eigenen Aufbau.")],
            [BADGE("beta"), ("Built from the maker’s manual or protocol and checked against a simulation, but not yet confirmed on the real device.", "Nach Handbuch oder Protokoll des Herstellers gebaut und gegen eine Simulation geprüft, aber noch nicht am echten Gerät bestätigt.")],
            [BADGE("alpha"), ("New and never tried on the real device. It may not work at all. Do not rely on it at an important event.", "Neu und noch nie am echten Gerät ausprobiert. Es kann sein, dass es gar nicht funktioniert. Nicht bei einer wichtigen Veranstaltung darauf verlassen.")],
            [BADGE("unk"), ("LJ Link sends, but it is not known whether the program can use it.", "LJ Link sendet, aber es ist nicht bekannt, ob das Programm es verwenden kann.")],
            [BADGE("gen"), ("A generic output that you connect yourself in the target program.", "Ein allgemeiner Ausgang, den du im Zielprogramm selbst zuordnest.")],
            [BADGE("plan"), ("Planned, not built yet.", "Geplant, noch nicht gebaut.")],
            [BADGE("no"), ("The device cannot receive this over a network.", "Das Gerät kann das nicht über ein Netzwerk empfangen.")],
        ]),
    )
    return (("Wiki – setup, network, light desks and use cases", "Wiki – Einrichtung, Netzwerk, Lichtpulte und Anwendungsfälle"),
            ("The LJ Link wiki: every use case step by step. Network setups (direct cable, switch, router, Wi-Fi), Pioneer, Denon, Serato, Ableton Link, grandMA2, grandMA3, Wolfmix, Daslight and OSC.",
             "Das LJ-Link-Wiki: jeder Anwendungsfall Schritt für Schritt. Netzwerk-Aufbauten (Direktkabel, Switch, Router, WLAN), Pioneer, Denon, Serato, Ableton Link, grandMA2, grandMA3, Wolfmix, Daslight und OSC."),
            ("Wiki", "Wiki"), ("LJ Link wiki", "LJ-Link-Wiki"),
            ("Everything about setting up LJ Link, with an honest status for every device.", "Alles zur Einrichtung von LJ Link, mit ehrlichem Stand für jedes Gerät."), body)


@page("wiki-quickstart.html", "Quick start", "Schnellstart")
def _():
    body = SEC(
        ADM("info", ("This page gets you from download to the first waveform in about five minutes, with the most common setup: Pioneer or Denon gear on one network switch. Other setups are on the [network](wiki-network-setups.html) and [use case](wiki-use-cases.html) pages.",
                     "Diese Seite bringt dich in etwa fünf Minuten vom Download zur ersten Waveform, mit dem häufigsten Aufbau: Pioneer- oder Denon-Geräte an einem Netzwerk-Switch. Andere Aufbauten stehen auf den Seiten [Netzwerk](wiki-network-setups.html) und [Anwendungsfälle](wiki-use-cases.html).")),
        H2("What you need", "Was du brauchst"),
        UL(("A computer with **macOS 12 or newer** or **Windows 10/11** (64 bit).", "Einen Computer mit **macOS 12 oder neuer** oder **Windows 10/11** (64 Bit)."),
           ("DJ gear with **Pro DJ Link** (Pioneer CDJ/XDJ/DJM) or **StageLinQ** (Denon Prime, SC6000), or **Serato DJ Pro** on the same computer.", "DJ-Geräte mit **Pro DJ Link** (Pioneer CDJ/XDJ/DJM) oder **StageLinQ** (Denon Prime, SC6000), oder **Serato DJ Pro** auf demselben Computer."),
           ("A **network switch** or a router and network cables. Many DJM mixers have LINK sockets that work as a small switch.", "Einen **Netzwerk-Switch** oder Router und Netzwerkkabel. Viele DJM-Mischpulte haben LINK-Buchsen, die wie ein kleiner Switch arbeiten."),
           ("Optional: a light desk (grandMA2, grandMA3, Wolfmix, Daslight, OSC program) for the tempo.", "Optional: ein Lichtpult (grandMA2, grandMA3, Wolfmix, Daslight, OSC-Programm) für das Tempo.")),
        H2("Five steps", "Fünf Schritte"),
        STEPS(("**Install.** Download the installer from the [download section](./#download) and open it. On the first start macOS and Windows warn once because the app is not signed yet: [how to open it anyway](wiki-install.html).",
               "**Installieren.** Den Installer im [Download-Bereich](./#download) laden und öffnen. Beim ersten Start warnen macOS und Windows einmal, weil die App noch nicht signiert ist: [So öffnest du sie trotzdem](wiki-install.html)."),
              ("**Allow the network.** macOS asks for the **local network**: allow it. Windows asks the firewall: tick **private networks** and allow. Without this LJ Link finds nothing.",
               "**Netzwerk erlauben.** macOS fragt nach dem **lokalen Netzwerk**: erlauben. Windows fragt die Firewall: **Private Netzwerke** anhaken und zulassen. Ohne das findet LJ Link nichts."),
              ("**Connect by cable.** Players, mixer and computer to the same switch. Switch **Wi-Fi off** on the computer. Give each player its own number (1, 2, 3 …).",
               "**Per Kabel verbinden.** Player, Mixer und Computer an denselben Switch. **WLAN am Computer ausschalten.** Jedem Player eine eigene Nummer geben (1, 2, 3 …)."),
              ("**Search.** Start LJ Link, the interface opens. Press **Search automatically**. Pioneer, Denon, Serato and Ableton Link are found at the same time, devices that come later are added by themselves.",
               "**Suchen.** LJ Link starten, die Oberfläche öffnet sich. **Automatisch suchen** drücken. Pioneer, Denon, Serato und Ableton Link werden gleichzeitig gefunden, später eingeschaltete Geräte kommen von selbst dazu."),
              ("**Load a track.** Pioneer: from a USB stick or SD card exported with rekordbox. Denon: from the device’s Engine library. The waveform appears.",
               "**Track laden.** Pioneer: von einem mit rekordbox exportierten USB-Stick oder einer SD-Karte. Denon: aus der Engine-Bibliothek des Geräts. Die Waveform erscheint.")),
        IMG("start.png", "Start screen of LJ Link with the button Search automatically", "Startbildschirm von LJ Link mit dem Knopf Automatisch suchen",
            ("The start screen. “Watch demo” shows three simulated players without any gear.", "Der Startbildschirm. „Demo ansehen“ zeigt drei simulierte Player ohne Geräte.")),
        H2("Next steps", "Wie es weitergeht"),
        UL(("Send the tempo to the desk: [light desks](wiki-lighting-desks.html).", "Tempo ans Pult schicken: [Lichtpulte](wiki-lighting-desks.html)."),
           ("Open the same view on a tablet: [waveforms on a tablet](wiki-case-tablet.html).", "Dieselbe Ansicht auf dem Tablet: [Waveforms auf dem Tablet](wiki-case-tablet.html)."),
           ("Nothing found? [Troubleshooting](wiki-troubleshooting.html#nothing-found).", "Nichts gefunden? [Fehlersuche](wiki-troubleshooting.html#nothing-found).")),
        ADM("tip", ("The interface starts in English. Switch it under ☰ → **Language** → **Deutsch**.", "Die Oberfläche startet auf Englisch. Umstellen unter ☰ → **Language** → **Deutsch**.")),
    )
    return (("Quick start", "Schnellstart"),
            ("LJ Link quick start: install, allow the network, connect by cable, search automatically and see the first DJ waveform in five minutes.",
             "LJ-Link-Schnellstart: installieren, Netzwerk erlauben, per Kabel verbinden, automatisch suchen und in fünf Minuten die erste DJ-Waveform sehen."),
            ("Start", "Start"), ("Quick start", "Schnellstart"),
            ("From download to the first waveform in five minutes.", "In fünf Minuten vom Download zur ersten Waveform."), body)


@page("wiki-install.html", "Install and update", "Installieren und aktualisieren")
def _():
    body = SEC(
        H2("Which file", "Welche Datei"),
        TABLE([("Computer", "Computer"), ("File", "Datei")], [
            [("Mac with Apple chip (M1 and newer)", "Mac mit Apple-Chip (M1 und neuer)"), "<code>LJ-Link-macos-arm64.dmg</code>"],
            [("Mac with Intel processor", "Mac mit Intel-Prozessor"), "<code>LJ-Link-macos-intel.dmg</code>"],
            ["Windows 10 / 11, 64 bit", "<code>LJ-Link-windows.exe</code>"],
        ]),
        P("Up to version 1.7.7 the files were called `LJ-Link-PRO-…`. For a while each release also carries copies under the old names, so older versions still find their update.",
          "Bis Version 1.7.7 hießen die Dateien `LJ-Link-PRO-…`. Eine Zeit lang liegen jedem Release zusätzlich Kopien unter den alten Namen bei, damit ältere Versionen ihr Update weiter finden."),
        P("Java is included, nothing else needs to be installed. Not sure which Mac you have? Apple menu → **About This Mac**: “Chip Apple M…” means Apple chip, “Processor Intel” means Intel.",
          "Java ist enthalten, sonst muss nichts installiert werden. Unsicher, welchen Mac du hast? Apple-Menü → **Über diesen Mac**: „Chip Apple M…“ heißt Apple-Chip, „Prozessor Intel“ heißt Intel."),
        H2("macOS", "macOS"),
        STEPS(("Open the `.dmg` and drag **LJ Link** into **Applications**.", "Die `.dmg` öffnen und **LJ Link** in **Programme** ziehen."),
              ("Start LJ Link once. macOS says *“LJ Link” Not Opened*: press **Done** (not *Move to Trash*).", "LJ Link einmal starten. macOS meldet *„LJ Link“ nicht geöffnet*: **Fertig** drücken (nicht *In den Papierkorb legen*)."),
              ("Open **System Settings** → **Privacy & Security** and scroll down.", "**Systemeinstellungen** → **Datenschutz & Sicherheit** öffnen und nach unten scrollen."),
              ("At *“LJ Link” was blocked* press **Open Anyway** and confirm with password or Touch ID, then **Open** once more.", "Bei *„LJ Link“ wurde blockiert* auf **Dennoch öffnen** drücken, mit Passwort oder Touch ID bestätigen, dann noch einmal **Öffnen**."),
              ("macOS asks about the **local network**: **Allow**. Without it no player is found.", "macOS fragt nach dem **lokalen Netzwerk**: **Erlauben**. Ohne das wird kein Player gefunden.")),
        ADM("note", ("Missed the network question? System Settings → **Privacy & Security** → **Local Network** → switch LJ Link on.", "Netzwerk-Frage verpasst? Systemeinstellungen → **Datenschutz & Sicherheit** → **Lokales Netzwerk** → LJ Link einschalten."),
            ("For experts, this removes the warning for good:", "Für Profis, damit verschwindet die Warnung dauerhaft:"), PRE('xattr -dr com.apple.quarantine "/Applications/LJ Link.app"')),
        H2("Windows", "Windows"),
        STEPS(("Start the downloaded installer (`.exe`). In the blue SmartScreen window press **More info**, then **Run anyway**.", "Den heruntergeladenen Installer (`.exe`) starten. Im blauen SmartScreen-Fenster **Weitere Informationen**, dann **Trotzdem ausführen** drücken."),
              ("Click through the installer.", "Den Installer durchklicken."),
              ("On the first start the firewall asks: tick **Private networks** and press **Allow access**.", "Beim ersten Start fragt die Firewall: **Private Netzwerke** anhaken und **Zugriff zulassen** drücken.")),
        ADM("warn", ("If Windows calls your network **Public**, the firewall blocks LJ Link even after you allowed it for private networks. Settings → Network & Internet → your connection → network profile **Private**.",
                     "Nennt Windows dein Netzwerk **Öffentlich**, blockiert die Firewall LJ Link, obwohl du es für private Netzwerke erlaubt hast. Einstellungen → Netzwerk und Internet → deine Verbindung → Netzwerkprofil **Privat**."),
            ("Missed the firewall question? Windows Security → Firewall & network protection → **Allow an app through firewall** → tick LJ Link for **Private**.",
             "Firewall-Frage verpasst? Windows-Sicherheit → Firewall- & Netzwerkschutz → **App durch die Firewall zulassen** → LJ Link bei **Privat** anhaken.")),
        H2("Where LJ Link lives", "Wo LJ Link läuft"),
        P("After the start an icon appears in the **menu bar** (Mac, top right) or next to the **clock** (Windows, bottom right, maybe behind the arrow). Its menu opens the interface, switches the privacy mode, checks for updates, opens **Report a problem or request a feature** and the [suite chat](wiki-chat.html) (alpha), and quits.",
          "Nach dem Start erscheint ein Symbol in der **Menüleiste** (Mac, oben rechts) oder neben der **Uhr** (Windows, unten rechts, eventuell hinter dem Pfeil). Sein Menü öffnet die Oberfläche, schaltet den Privatsphäre-Modus, sucht nach Updates, öffnet **Problem melden oder Wunsch äußern** und den [Suite-Chat](wiki-chat.html) (Alpha) und beendet das Programm."),
        P("A second start does not run LJ Link twice: it only opens the interface of the running one.", "Ein zweiter Start lässt LJ Link nicht doppelt laufen: Er öffnet nur die Oberfläche des laufenden."),
        H2("Quitting", "Beenden", "quit"),
        P("**Quit** in the menu of the icon first shows a small window with the heading **Note**: LJ Link is a community project. There you can rate LJ Link with 1 to 5 stars (optional; click the chosen star again for no rating) and press **Give feedback**, which opens [Report a problem or request a feature](wiki-troubleshooting.html#report) with the rating filled in; LJ Link keeps running. **Share link** copies the address of the website. **Quit** ends LJ Link and is the default button, so Enter quits too; closing the window (or Escape) cancels.",
          "**Beenden** im Menü des Symbols zeigt vorher ein kleines Fenster mit der Überschrift **Hinweis**: LJ Link ist ein Community-Projekt. Dort kannst du LJ Link mit 1 bis 5 Sternen bewerten (optional; nochmal auf den gewählten Stern klicken heißt keine Bewertung) und **Feedback geben** drücken; das öffnet [Problem melden oder Wunsch äußern](wiki-troubleshooting.html#report) mit der Bewertung, LJ Link läuft weiter. **Link teilen** kopiert die Adresse der Website. **Beenden** beendet LJ Link und ist der Standardknopf, also beendet auch Enter; Fenster schließen (oder Escape) bricht ab."),
        P("Nothing is sent from this window. Tick **Don't show this again when quitting** to quit at once next time. Settings → **Quit** → **Show note when quitting** (shown only on the computer running LJ Link, and only while the program icon is shown) brings the note back or switches it off. An update quits without the note.",
          "Aus diesem Fenster wird nichts gesendet. Mit dem Häkchen **Beim Beenden nicht mehr anzeigen** beendet LJ Link beim nächsten Mal sofort. Einstellungen → **Beenden** → **Hinweis beim Beenden anzeigen** (nur auf dem Rechner sichtbar, auf dem LJ Link läuft, und nur, wenn das Programm-Symbol angezeigt wird) holt den Hinweis zurück oder schaltet ihn ab. Ein Update beendet ohne den Hinweis."),
        ADM("alpha", ("New in 1.7.9 and not tested by hand yet, on the Mac and on Windows.", "Neu in 1.7.9 und noch nicht von Hand getestet, weder am Mac noch unter Windows.")),
        H2("Updates", "Updates"),
        P("About 15 seconds after the start (only when the program icon is shown) and when the interface is loaded, at most once an hour, LJ Link checks whether a new version exists and tells you. Only the computer running LJ Link asks GitHub, also when a tablet loads the page. **Check for updates** in the menu of the icon downloads and installs it: on a Mac the app is replaced and restarts, on Windows the installer opens. Settings stay. A download is only installed if it matches the checksum GitHub publishes for it.",
          "Etwa 15 Sekunden nach dem Start (nur wenn das Programm-Symbol angezeigt wird) und beim Laden der Oberfläche, höchstens einmal pro Stunde, prüft LJ Link, ob es eine neue Version gibt, und sagt Bescheid. Es fragt immer nur der Rechner, auf dem LJ Link läuft, auch wenn ein Tablet die Seite lädt. **Nach Updates suchen** im Menü des Symbols lädt und installiert sie: Auf dem Mac wird die App ersetzt und startet neu, unter Windows öffnet sich der Installer. Einstellungen bleiben erhalten. Installiert wird nur ein Download, der zur Prüfsumme passt, die GitHub dafür angibt."),
        P("The automatic check can be switched off: Settings → **Updates** → **Check for updates automatically** (shown only on the computer running LJ Link). **Check for updates** in the icon menu always works.",
          "Die automatische Prüfung lässt sich abschalten: Einstellungen → **Updates** → **Automatisch nach Updates suchen** (nur auf dem Rechner sichtbar, auf dem LJ Link läuft). **Nach Updates suchen** im Menü des Symbols geht immer."),
        ADM("note", ("Update finds nothing although a newer version exists? Download the newest version once from the [release page](https://github.com/skyplayser/LJ-Link/releases/latest) and install it.",
                     "Das Update findet nichts, obwohl es eine neuere Version gibt? Die neueste Version einmal von der [Release-Seite](https://github.com/skyplayser/LJ-Link/releases/latest) laden und installieren.")),
        ADM("tip", ("The check needs the internet. In a show network without internet it just says it could not reach GitHub; everything else works as usual. Update at home, not at the gig.",
                    "Die Prüfung braucht Internet. In einem Show-Netz ohne Internet meldet sie nur, dass GitHub nicht erreichbar ist; alles andere läuft wie gewohnt. Zu Hause aktualisieren, nicht auf dem Gig.")),
        ADM("note", ("Versions 1.2.x cannot update themselves (“Handshake failed”). Install the newest version once by hand.", "Versionen 1.2.x können sich nicht selbst aktualisieren („Handshake failed“). Die neueste Version einmal von Hand installieren.")),
    )
    return (("Install and update", "Installieren und aktualisieren"),
            ("Install LJ Link on macOS and Windows: which file, how to open an unsigned app, local network and firewall permission, menu bar icon and updates.",
             "LJ Link auf macOS und Windows installieren: welche Datei, eine nicht signierte App öffnen, lokales Netzwerk und Firewall erlauben, Menüleisten-Symbol und Updates."),
            ("Start", "Start"), ("Install and update", "Installieren und aktualisieren"),
            ("macOS and Windows, with the warnings on the first start and the permissions LJ Link needs.", "macOS und Windows, mit den Warnungen beim ersten Start und den Rechten, die LJ Link braucht."), body)


@page("wiki-interface.html", "The interface", "Die Oberfläche")
def _():
    body = SEC(
        H2("Waveform view", "Waveform-Ansicht"),
        IMG("waveform.png", "Waveform view with several decks", "Waveform-Ansicht mit mehreren Decks"),
        P("Every deck is a row: on the left the data of the player, on the right the waveforms.", "Jedes Deck ist eine Zeile: links die Daten des Players, rechts die Waveforms."),
        TABLE([("Element", "Element"), ("Meaning", "Bedeutung")], [
            [("**PLAYER / TRACK**", "**PLAYER / TRACK**"), ("player number and track number on the medium", "Nummer des Players und des Tracks auf dem Medium")],
            [("Big time", "Große Zeit"), ("elapsed time in minutes, seconds and milliseconds, below **REMAIN**", "gespielte Zeit in Minuten, Sekunden und Millisekunden, darunter **REST**")],
            [("**TEMPO**", "**TEMPO**"), ("pitch in percent", "Pitch in Prozent")],
            [("BPM box", "BPM-Kasten"), ("current tempo, **orange** on the tempo master", "aktuelles Tempo, **orange** beim Tempo-Master")],
            [("**MT / SYNC / PAUSE**", "**MT / SYNC / PAUSE**"), ("master, sync on, paused", "Master, Sync an, pausiert")],
            [("Red **LIVE** frame", "Rote **LIVE**-Umrandung"), ("the deck is on air at the mixer", "das Deck ist am Mixer auf Sendung")],
            [("Cyan bar top left", "Cyanfarbener Balken oben links"), ("mixer channel: on air or off with Pioneer, the real fader level with Denon", "Mixerkanal: bei Pioneer auf Sendung oder aus, bei Denon die echte Fader-Stellung")],
            [("Upper waveform", "Obere Waveform"), ("scrolls past the playhead, the played part is darker", "läuft am Playhead vorbei, der gespielte Teil ist abgedunkelt")],
            [("Lower waveform", "Untere Waveform"), ("the whole track with playhead and remaining time", "der ganze Track mit Playhead und Restzeit")],
            [("Flags A–H, red triangles", "Flaggen A–H, rote Dreiecke"), ("hot cues in their colours, memory cues", "Hot Cues in ihren Farben, Memory Cues")],
            [("Orange area ↻ 8", "Oranger Bereich ↻ 8"), ("loop, the active one brighter, with its length in beats", "Loop, der aktive kräftiger, mit Länge in Beats")],
            [("Ticks, red ones", "Striche, rote"), ("beat grid, red at the start of a bar", "Beatgrid, rot am Taktanfang")],
            [("Green **SEND BPM**", "Grünes **SEND BPM**"), ("this deck gives the tempo to the light desk", "dieses Deck gibt das Tempo ans Lichtpult")],
            [("**Not supported** / **No track data** with a sentence on the waveform", "**Nicht unterstützt** / **Keine Trackdaten** mit einem Satz auf der Waveform"), ("the player reports a track, but no title arrived within 30 seconds (1.7.10 and newer, alpha). The link **Help** or **What can I do?** leads to [tracks and waveforms](wiki-troubleshooting.html#tracks-and-waveforms)", "der Player meldet einen Track, aber nach 30 Sekunden kam kein Titel (ab 1.7.10, Alpha). Der Link **Hilfe** bzw. **Was kann ich tun?** führt zu [Tracks und Waveforms](wiki-troubleshooting.html#tracks-and-waveforms)")],
        ]),
        P("A grey line shows notes about the network, already in the search view and later above the decks, for example **ShowKontrol runs on this computer.** or **ShowKontrol is running on the network.** (1.7.10 and newer, alpha). Do not run ShowKontrol and LJ Link on the same computer, see [troubleshooting](wiki-troubleshooting.html#showkontrol).",
          "Eine graue Zeile zeigt Hinweise zum Netz, schon in der Suchansicht und später über den Decks, zum Beispiel **ShowKontrol läuft auf diesem Computer.** oder **ShowKontrol läuft im Netz.** (ab 1.7.10, Alpha). ShowKontrol und LJ Link nicht auf demselben Computer betreiben, siehe [Fehlersuche](wiki-troubleshooting.html#showkontrol)."),
        P("A **click on a deck** opens everything the player reports: device, status, tempo, loop, medium, track, position, cues and the raw packet.",
          "Ein **Klick auf ein Deck** öffnet alles, was der Player meldet: Gerät, Status, Tempo, Loop, Medium, Track, Position, Cues und das rohe Datenpaket."),
        H2("Toolbar and views", "Werkzeugleiste und Ansichten"),
        UL(("**Zoom − / +**: how many seconds the upper waveform shows.", "**Zoom − / +**: wie viele Sekunden die obere Waveform zeigt."),
           ("**VIEW**: both waveforms, detail only or overview only.", "**VIEW**: beide Waveforms, nur Detail oder nur Übersicht."),
           ("**Tabs** WAVEFORM and MIXER; **LINK** opens the light desk link, **SEND BPM** chooses the deck for the tempo.", "**Reiter** WAVEFORM und MIXER; **LINK** öffnet den Lichtpult-Link, **SEND BPM** wählt das Deck für das Tempo."),
           ("**Full screen** for the desk.", "**Vollbild** fürs Pult.")),
        H2("Mixer tab", "Reiter Mixer"),
        IMG("mixer.png", "Mixer tab with channels", "Reiter Mixer mit Kanälen"),
        ADM("note", ("Pro DJ Link only tells which channel is on air. **No DJM sends fader positions or EQ.** With a Pioneer mixer the bar shows on air or off and the knobs stay empty. Denon devices send the real fader levels, but no EQ. The demo simulates both and marks it *SIMULATED*.",
                     "Pro DJ Link überträgt nur, welcher Kanal auf Sendung ist. **Kein DJM sendet Fader-Stellungen oder EQ.** Mit einem Pioneer-Mixer zeigt der Balken auf Sendung oder aus, die Knöpfe bleiben leer. Denon-Geräte senden die echten Fader-Stellungen, aber keinen EQ. Die Demo simuliert beides und markiert es mit *SIMULIERT*.")),
        P("Since 1.7.10 a Pioneer mixer appears here as soon as it announces itself in the network, with model, number and address (alpha, not tested on a real mixer). Tempo and master from the mixer only come if it sends a mixer status LJ Link can read; if none has arrived once LJ Link has listened for 5 seconds, the tab says **Mixer recognised (Alpha), but it sends no data LJ Link can read (tempo, master)**. ON AIR per channel is read from the players in both cases.",
          "Seit 1.7.10 erscheint ein Pioneer-Mixer hier, sobald er sich im Netz anmeldet, mit Modell, Nummer und Adresse (Alpha, nicht an einem echten Mixer getestet). Tempo und Master vom Mixer kommen nur, wenn er einen Mixer-Status sendet, den LJ Link lesen kann; kam keiner, nachdem LJ Link 5 Sekunden zugehört hat, steht im Reiter **Mixer erkannt (Alpha), sendet aber keine Daten, die LJ Link lesen kann (Tempo, Master)**. ON AIR je Kanal liest LJ Link in beiden Fällen aus den Playern."),
        H2("Settings", "Einstellungen"),
        IMG("settings.png", "Settings window", "Einstellungsfenster"),
        UL(("**Waveform colours**: RGB like on the player or classic blue.", "**Waveform-Farben**: RGB wie am Player oder klassisch Blau."),
           ("**Display**: day or night.", "**Anzeige**: Tag oder Nacht."),
           ("**Language**: English or German, saved per browser.", "**Sprache**: Englisch oder Deutsch, pro Browser gespeichert."),
           ("**Devices**: with many devices or several floors tick devices on or off.", "**Geräte**: bei vielen Geräten oder mehreren Floors Geräte an- und abhaken."),
           ("**Light desk link**: see [light desks](wiki-lighting-desks.html).", "**Lichtpult-Link**: siehe [Lichtpulte](wiki-lighting-desks.html)."),
           ("**Ableton Link**: lead the Link session with the DJ tempo, beats and bars (works with Daslight), see [Ableton Link](wiki-ableton-link.html#send).", "**Ableton Link**: die Link-Session mit DJ-Tempo, Beats und Takten führen (läuft mit Daslight), siehe [Ableton Link](wiki-ableton-link.html#send)."),
           ("**Screen → Keep screen awake – Alpha**: the screen of this device stays on while LJ Link is shown. On by default, saved per browser. See [below](#keep-awake).", "**Bildschirm → Bildschirm wach halten – Alpha**: Der Bildschirm dieses Geräts bleibt an, solange LJ Link angezeigt wird. Standardmäßig an, pro Browser gespeichert. Siehe [unten](#keep-awake)."),
           ("**Suite chat – Alpha** (new in 1.7.11): chat with the other suite programs in this network, on by default, shown only on the computer running LJ Link, see [suite chat](wiki-chat.html).", "**Suite-Chat – Alpha** (neu in 1.7.11): Chat mit den anderen Suite-Programmen in diesem Netzwerk, standardmäßig an, nur auf dem Rechner sichtbar, auf dem LJ Link läuft, siehe [Suite-Chat](wiki-chat.html)."),
           ("**Updates → Check for updates automatically**: shown only on the computer running LJ Link, see [updates](wiki-install.html#updates).", "**Updates → Automatisch nach Updates suchen**: nur auf dem Rechner sichtbar, auf dem LJ Link läuft, siehe [Updates](wiki-install.html#updates)."),
           ("**Quit → Show note when quitting – Alpha** (new in 1.7.9): shown only on the computer running LJ Link and only while the program icon is shown, see [quitting](wiki-install.html#quit).", "**Beenden → Hinweis beim Beenden anzeigen – Alpha** (neu in 1.7.9): nur auf dem Rechner sichtbar, auf dem LJ Link läuft, und nur, wenn das Programm-Symbol angezeigt wird, siehe [Beenden](wiki-install.html#quit)."),
           ("**Feedback → Report a problem or request a feature**: opens the report window, see [troubleshooting](wiki-troubleshooting.html#report).", "**Feedback → Problem melden oder Wunsch äußern**: öffnet das Meldefenster, siehe [Fehlersuche](wiki-troubleshooting.html#report)."),
           ("**Start → Start animation** (new in 1.7.12): when LJ Link opens, the Link-Suite logo fans out all suite programs and LJ Link flies onto its logo on the start page (about 2.5 s). Once per program start in each browser, not after a reload or with a deep link such as /#chat; any key, click or tap skips it. With “Reduce motion” in the system it only fades in. On by default, saved per browser.", "**Start → Startanimation** (neu in 1.7.12): Beim Öffnen fächert das Link-Suite-Logo alle Suite-Programme auf, und LJ Link fliegt auf sein Logo auf der Startseite (etwa 2,5 s). Einmal je Programmstart in jedem Browser, nicht nach dem Neuladen oder bei einem Direktlink wie /#chat; jede Taste, ein Klick oder Tipp überspringt sie. Mit „Bewegung reduzieren“ im System blendet sie nur ein. Standardmäßig an, pro Browser gespeichert."),
           ("**Disconnect** ends the running connection.", "**Verbindung trennen** beendet die laufende Verbindung.")),
        P("**Get Link-Suite** (new in 1.7.12): if the launcher [Link-Suite](https://skyplayser.github.io/Link-Suite/) is not installed on the computer running LJ Link, a small card below the three steps of the start page offers it. LJ Link only looks on this computer whether it is installed; this check sends nothing to the network. Only when you click **Get Link-Suite** does your browser open its page. **Don't show again** hides the card in this browser. Never shown on a tablet.",
          "**Link-Suite laden** (neu in 1.7.12): Ist der Launcher [Link-Suite](https://skyplayser.github.io/Link-Suite/) auf dem Rechner mit LJ Link nicht installiert, bietet ihn eine kleine Karte unter den drei Schritten der Startseite an. LJ Link sieht nur auf diesem Rechner nach, ob er installiert ist; für diese Prüfung geht nichts ins Netz. Erst wenn du auf **Link-Suite laden** klickst, öffnet dein Browser seine Seite. **Nicht mehr zeigen** blendet die Karte in diesem Browser aus. Auf Tablets nie."),
        H2("Keep the screen awake", "Bildschirm wach halten", "keep-awake"),
        ADM("warn", ("New in 1.7.6 and alpha: **works on a Mac**. On the iPad it has not kept the screen on reliably so far; Android tablets and Windows PCs are not tested yet. For iPad and iPhone see [the reliable way](wiki-case-tablet.html#keep-awake-ios).", "Neu in 1.7.6 und Alpha: **läuft am Mac**. Auf dem iPad hat es den Bildschirm bisher nicht zuverlässig angehalten; Android-Tablets und Windows-PCs sind noch nicht getestet. Für iPad und iPhone siehe [den sicheren Weg](wiki-case-tablet.html#keep-awake-ios).")),
        P("In a booth nobody touches the device for hours, so screens dim and lock. Menu (☰) → **Screen** → **Keep screen awake – Alpha** prevents that. It is on by default and stays as set in each browser, also after a reload. The line below the setting shows the status.",
          "In der Booth fasst stundenlang niemand das Gerät an, also dunkeln Bildschirme ab und sperren. Menü (☰) → **Bildschirm** → **Bildschirm wach halten – Alpha** verhindert das. Die Einstellung ist standardmäßig an und bleibt in jedem Browser so, wie sie gesetzt ist, auch nach dem Neuladen. Die Zeile unter der Einstellung zeigt den Status."),
        TABLE([("Where", "Wo"), ("What happens", "Was passiert")], [
            [("Browser on the computer with LJ Link (`http://127.0.0.1:8080`)", "Browser am Computer mit LJ Link (`http://127.0.0.1:8080`)"), ("the screen stays on at once, no tap needed. Status: **Active – the screen stays on**", "der Bildschirm bleibt sofort an, ohne Tippen. Status: **Aktiv – der Bildschirm bleibt an**")],
            [("iPad or tablet over the network (`http://<address>:8080`)", "iPad oder Tablet über das Netzwerk (`http://<Adresse>:8080`)"), ("a strip right below the header shows **☼ Tap here once to keep the screen on**. Tap the strip or anywhere else on the page once, then LJ Link tries to keep the screen on: the status shows **Starting the video …**, after a few seconds **Active (video) – the screen stays on**. If the video does not start (after about 6 seconds) or iOS stops it, the status shows **Video stopped – please tap the page** and the strip says **☼ The screen may turn off – tap here to restart keep-awake**; tap once more. Without HTTPS this is only a workaround (alpha) that has not been reliable on the iPad so far; there use auto-lock **Never**, see [the reliable way](wiki-case-tablet.html#keep-awake-ios)", "ein Streifen direkt unter der Kopfzeile zeigt **☼ Einmal hier tippen, damit der Bildschirm an bleibt**. Einmal auf den Streifen oder irgendwo sonst auf die Seite tippen, dann versucht LJ Link, den Bildschirm anzuhalten: Der Status zeigt **Video startet …**, nach ein paar Sekunden **Aktiv (Video) – der Bildschirm bleibt an**. Läuft das Video nicht an (nach etwa 6 Sekunden) oder hält iOS es an, zeigt der Status **Video angehalten – bitte auf die Seite tippen**, und der Streifen sagt **☼ Der Bildschirm kann ausgehen – hier tippen, um den Wachmodus neu zu starten**; noch einmal tippen. Ohne HTTPS ist das nur ein Notbehelf (Alpha), der auf dem iPad bisher nicht zuverlässig war; dort die automatische Sperre auf **Nie** stellen, siehe [den sicheren Weg](wiki-case-tablet.html#keep-awake-ios)")],
            [("Page hidden (other tab, app or minimised)", "Seite verdeckt (anderer Tab, andere App oder minimiert)"), ("Status: **Paused while the page is hidden**. When you come back, the last state applies again; if the video was stopped meanwhile, the status shows **Video stopped – please tap the page**, then tap once more", "Status: **Pausiert, solange die Seite verdeckt ist**. Beim Zurückkommen gilt wieder der letzte Stand; wurde das Video inzwischen angehalten, zeigt der Status **Video angehalten – bitte auf die Seite tippen**, dann noch einmal tippen")],
            [("Setting off", "Einstellung aus"), ("the device dims and locks as usual. Status: **Off**", "das Gerät dunkelt ab und sperrt wie gewohnt. Status: **Aus**")],
        ]),
        P("All status texts below the setting (shown as „Status: …“):", "Alle Statustexte unter der Einstellung (angezeigt als „Status: …“):"),
        TABLE([("Status", "Status"), ("Meaning", "Bedeutung")], [
            [("**Active – the screen stays on**", "**Aktiv – der Bildschirm bleibt an**"), ("the browser's own screen lock is on (computer itself or HTTPS)", "die eigene Bildschirmsperre des Browsers ist an (am Computer selbst oder mit HTTPS)")],
            [("**Waiting for a tap – tap the page once**", "**Wartet auf Tippen – einmal auf die Seite tippen**"), ("over the network; nothing runs until the first tap", "über das Netzwerk; bis zum ersten Tipp läuft nichts")],
            [("**Starting the video …**", "**Video startet …**"), ("after the tap, LJ Link checks whether the silent video really plays", "nach dem Tipp prüft LJ Link, ob das stille Video wirklich läuft")],
            [("**Active (video) – the screen stays on**", "**Aktiv (Video) – der Bildschirm bleibt an**"), ("the video plays; LJ Link tries to keep the screen on this way (alpha, on the iPad not reliable so far)", "das Video läuft; LJ Link versucht so, den Bildschirm anzuhalten (Alpha, auf dem iPad bisher nicht zuverlässig)")],
            [("**Video stopped – please tap the page**", "**Video angehalten – bitte auf die Seite tippen**"), ("the video did not start within about 6 seconds or was stopped; tap once more", "das Video lief nicht innerhalb von etwa 6 Sekunden an oder wurde angehalten; noch einmal tippen")],
            [("**Paused while the page is hidden**", "**Pausiert, solange die Seite verdeckt ist**"), ("other tab or app; continues when you come back", "anderer Tab oder andere App; geht beim Zurückkommen weiter")],
            [("**Not available in this browser**", "**In diesem Browser nicht verfügbar**"), ("neither way works here; set auto-lock on the device to **Never**", "keiner der Wege geht hier; automatische Sperre am Gerät auf **Nie** stellen")],
            [("**Off**", "**Aus**"), ("setting switched off", "Einstellung ausgeschaltet")],
        ]),
        P("On the video way a note below the setting adds: on an iPad or iPhone without HTTPS this is a stopgap; more reliable is auto-lock **Never** with the charger connected, and Low Power Mode off (on the iPhone it shortens auto-lock to 30 seconds, probably on the iPad too). See [the reliable way](wiki-case-tablet.html#keep-awake-ios).",
          "Auf dem Video-Weg ergänzt ein Hinweis unter der Einstellung: Auf iPad oder iPhone ohne HTTPS ist das ein Notbehelf; sicherer ist die automatische Sperre **Nie** am Netzteil, dazu Stromsparmodus aus (auf dem iPhone verkürzt er die automatische Sperre auf 30 Sekunden, auf dem iPad vermutlich auch). Siehe [den sicheren Weg](wiki-case-tablet.html#keep-awake-ios)."),
        P("On a **Mac**, LJ Link itself also keeps the computer from falling asleep while at least one browser is connected, also an iPad, so the tablet does not lose LJ Link. About a minute after the last browser is closed the Mac may sleep again. Whether the Mac display stays on is up to the page in its browser. On Windows LJ Link does not do this part yet.",
          "Auf dem **Mac** verhindert LJ Link selbst außerdem den Ruhezustand des Computers, solange mindestens ein Browser verbunden ist, auch ein iPad, damit das Tablet LJ Link nicht verliert. Etwa eine Minute nachdem der letzte Browser geschlossen wurde, darf der Mac wieder schlafen. Ob das Display des Macs anbleibt, entscheidet die Seite in seinem Browser. Unter Windows macht LJ Link diesen Teil noch nicht."),
        P("Screen goes dark anyway? See [troubleshooting](wiki-troubleshooting.html#screen-off).", "Bildschirm geht trotzdem aus? Siehe [Fehlersuche](wiki-troubleshooting.html#screen-off)."),
        H2("Privacy mode", "Privatsphäre-Modus"),
        P("Switched only from the program icon. LJ Link then sends no titles, artists, albums, genres, labels, comments or covers at all, also not to tablets. Waveforms, times, tempo and cues stay. Details: [livestream and privacy mode](wiki-case-stream.html).",
          "Wird nur über das Programm-Symbol geschaltet. LJ Link sendet dann gar keine Titel, Artists, Alben, Genres, Labels, Kommentare und Cover mehr, auch nicht an Tablets. Waveforms, Zeiten, Tempo und Cues bleiben. Details: [Livestream und Privatsphäre-Modus](wiki-case-stream.html)."),
        H2("Demo mode", "Demo-Modus"),
        P("**Watch demo** on the start screen shows three simulated players with moving waveforms, mixer values and cues. Good for trying the interface at home. The demo never sends anything to a light desk.",
          "**Demo ansehen** auf dem Startbildschirm zeigt drei simulierte Player mit laufenden Waveforms, Mixerwerten und Cues. Gut zum Ausprobieren zu Hause. Die Demo sendet nie etwas an ein Lichtpult."),
    )
    return (("The interface", "Die Oberfläche"),
            ("A tour of the LJ Link interface: waveform view, decks, cues, loops, beat grid, LIVE frame, mixer tab, settings, keeping the screen awake, privacy and demo mode.",
             "Ein Rundgang durch die LJ-Link-Oberfläche: Waveform-Ansicht, Decks, Cues, Loops, Beatgrid, LIVE-Rahmen, Mixer-Reiter, Einstellungen, Bildschirm wach halten, Privatsphäre- und Demo-Modus."),
            ("Start", "Start"), ("The interface", "Die Oberfläche"),
            ("What every element on the screen means.", "Was jedes Element auf dem Bildschirm bedeutet."), body)


@page("wiki-chat.html", "Suite chat", "Suite-Chat")
def _():
    body = SEC(
        ADM("alpha", ("New in 1.7.11. Tried only on one Mac, with several suite programs on the same computer. **Not tested between two computers and not on Windows.** Do not rely on it at an important event; keep a radio or a phone ready.",
                      "Neu in 1.7.11. Nur an einem Mac ausprobiert, mit mehreren Suite-Programmen auf demselben Computer. **Zwischen zwei Computern und unter Windows nicht getestet.** Nicht bei einer wichtigen Veranstaltung darauf verlassen; Funkgerät oder Telefon bereithalten.")),
        H2("What it is", "Was es ist"),
        P("Lighting booth, DJ booth and VJ often have to shout across the floor: “drop in 30 seconds”, “more fog?”. The suite chat is one chat room for LJ Link and the other programs of the suite that have the chat, for example VJ-Link and [LJL Link](wiki-ljl-link.html#chat) on the DJ’s Mac. Every suite program in the same network joins by itself. There is **no server** and no account: whoever is in the network with a suite program is in the room, also when LJ Link is not running.",
          "Lichtpult, DJ-Booth und VJ müssen sich oft quer über die Tanzfläche etwas zurufen: „Drop in 30 Sekunden“, „mehr Nebel?“. Der Suite-Chat ist ein Chatraum für LJ Link und die anderen Programme der Suite, die den Chat haben, zum Beispiel VJ-Link und [LJL Link](wiki-ljl-link.html#chat) auf dem Mac des DJs. Jedes Suite-Programm im selben Netzwerk kommt von selbst dazu. Es gibt **keinen Server** und kein Konto: Wer mit einem Suite-Programm im Netzwerk ist, ist im Raum, auch wenn LJ Link gerade nicht läuft."),
        H2("Open the chat", "Chat öffnen", "open"),
        UL(("**Chat** button at the bottom right of the interface. It is shown only in the browser on the computer running LJ Link, **not on a tablet** or phone.",
            "Knopf **Chat** unten rechts in der Oberfläche. Er erscheint nur im Browser auf dem Rechner, auf dem LJ Link läuft, **nicht auf einem Tablet** oder Handy."),
           ("Or the program icon (menu bar or next to the clock) → **Open suite chat (alpha)**. This opens the interface with the chat open.",
            "Oder das Programm-Symbol (Menüleiste bzw. neben der Uhr) → **Suite-Chat öffnen (Alpha)**. Das öffnet die Oberfläche mit offenem Chat.")),
        P("The first time, the chat asks two things: **Name – What is your name?** (for example DJ David) and **Position – Where are you?** (for example FOH, DJ Booth, Bar). Then **Join chat**. Both are shown with every message, as “name (position) · LJ Link”. **Change name** at the top of the chat changes them later. The top line shows who is in the room.",
          "Beim ersten Öffnen fragt der Chat zwei Dinge: **Name – Wie heißt du?** (zum Beispiel DJ David) und **Position – Wo stehst du?** (zum Beispiel FOH, DJ Booth, Bar). Dann **Chat betreten**. Beides steht bei jeder Nachricht, als „Name (Position) · LJ Link“. **Name ändern** oben im Chat ändert es später. Die obere Zeile zeigt, wer im Raum ist."),
        P("When you join or switch the chat on again, the others send their last messages again (up to 20 each), so you see what was written just before. This can take up to about 12 seconds. Every message shows a time: for new messages the time they arrived here, for these earlier ones the time they were sent.",
          "Beim Betreten oder Wiedereinschalten schicken die anderen ihre letzten Nachrichten noch einmal (bis zu 20 je Programm), so siehst du, was kurz vorher geschrieben wurde. Das kann bis etwa 12 Sekunden dauern. Jede Nachricht zeigt eine Uhrzeit: bei neuen Nachrichten die Zeit, zu der sie hier ankam, bei diesen früheren die Zeit, zu der sie gesendet wurde."),
        H2("Write and EMERGENCY", "Schreiben und EMERGENCY", "emergency"),
        P("Type into **Message to everyone** and press **Send** (or Enter). Every message goes to everyone in the room; there are no private messages.",
          "In **Nachricht an alle** tippen und **Senden** drücken (oder Enter). Jede Nachricht geht an alle im Raum; private Nachrichten gibt es nicht."),
        P("**EMERGENCY** next to **Send** is for when it really matters. With an empty text field it sends “EMERGENCY – please come at once!”. Everyone else gets a pop-up at once:",
          "**EMERGENCY** neben **Senden** ist für den Fall, dass es wirklich wichtig ist. Mit leerem Textfeld schickt es „EMERGENCY – bitte sofort kommen!“. Bei allen anderen erscheint sofort ein Popup:"),
        UL(("at the bottom right of the screen, with a **yellow blinking border**, with name, position, program and text;",
            "unten rechts auf dem Bildschirm, mit **gelb blinkendem Rand**, mit Name, Position, Programm und Text;"),
           ("in LJ Link also as a **window of its own**, always in front, also when no browser is open (LJ Link often runs only as the program icon). It does not take the keyboard from the program you are working in;",
            "in LJ Link zusätzlich als **eigenes Fenster**, immer im Vordergrund, auch wenn kein Browser offen ist (LJ Link läuft oft nur als Programm-Symbol). Es nimmt dem Programm, in dem du gerade arbeitest, nicht die Tastatur weg;"),
           ("it stays until **OK**. OK in the window or in the browser closes it in both. With two or more open, **Close all** appears; it closes only the ones already shown, one that arrives just then stays open.",
            "es bleibt, bis **OK** gedrückt wird. OK im Fenster oder im Browser schließt es an beiden Stellen. Ab zwei offenen gibt es **Alle schließen**; es schließt nur die schon gezeigten, ein gerade angekommener bleibt offen.")),
        ADM("note", ("The chat **never plays a sound**: the output of the computer may be connected to the mixer. The word EMERGENCY stays the same in every language.",
                     "Der Chat **spielt nie einen Ton**: Der Ausgang des Computers hängt womöglich am Mixer. Das Wort EMERGENCY bleibt in jeder Sprache gleich.")),
        ADM("warn", ("EMERGENCY is **no alarm or safety system** and no substitute for emergency calls, fire alarms, radios or security staff. Messages can be lost or arrive late, and anyone in the network can write under another name.",
                     "EMERGENCY ist **keine Alarm- oder Sicherheitstechnik** und kein Ersatz für Notruf, Brandmeldeanlage, Funk oder Sicherheitspersonal. Nachrichten können verloren gehen oder verspätet ankommen, und jeder im Netzwerk kann unter fremdem Namen schreiben.")),
        H2("New messages", "Neue Nachrichten", "unread"),
        TABLE([("What you see", "Was du siehst"), ("Meaning", "Bedeutung")], [
            [("Number at the **Chat** button", "Zahl am Knopf **Chat**"), ("new messages from the others while the chat is closed; your own messages and the earlier messages sent when you join do not count", "neue Nachrichten der anderen, solange der Chat zu ist; die eigenen und die früheren Nachrichten, die beim Betreten nachkommen, zählen nicht")],
            [("Number at the program icon, **Open suite chat (alpha) – 2 new** in its menu", "Zahl am Programm-Symbol, **Suite-Chat öffnen (Alpha) – 2 neu** in seinem Menü"), ("the same, also when no browser is open", "dasselbe, auch wenn kein Browser offen ist")],
            [("**Chat** button blinks yellow (the circle at the program icon too)", "Knopf **Chat** blinkt gelb (der Kreis am Programm-Symbol auch)"), ("an EMERGENCY came that you have not seen in the chat yet. It blinks until you open the chat; **OK** on the pop-up does not stop it. With “reduce motion” on in the system the button stays yellow instead of blinking (on a Mac also the window border and the circle at the program icon)", "ein EMERGENCY kam, den du im Chat noch nicht gesehen hast. Es blinkt, bis du den Chat öffnest; **OK** im Popup beendet es nicht. Mit „Bewegung reduzieren“ im System bleibt der Knopf gelb, statt zu blinken (am Mac auch der Fensterrand und der Kreis am Programm-Symbol)")],
        ]),
        H2("Switch it off", "Abschalten", "off"),
        P("Menu (☰) → **Suite chat – Alpha** → **Chat with all suite programs in this network**. On by default; shown only on the computer running LJ Link. Switched off, LJ Link neither sends nor reads chat messages, the **Chat** button goes, the menu item at the program icon is greyed out, open pop-ups close, and LJ Link forgets every chat message in memory (the browser empties its list too). Switched on again, the others send their last messages.",
          "Menü (☰) → **Suite-Chat – Alpha** → **Chat mit allen Suite-Programmen in diesem Netzwerk**. Standardmäßig an; nur auf dem Rechner sichtbar, auf dem LJ Link läuft. Ausgeschaltet sendet und liest LJ Link keine Chat-Nachrichten, der Knopf **Chat** verschwindet, der Menüpunkt am Programm-Symbol ist ausgegraut, offene Popups gehen zu, und LJ Link vergisst alle Chat-Nachrichten im Speicher (auch der Browser leert seine Liste). Wieder eingeschaltet schicken die anderen ihre letzten Nachrichten."),
        H2("Limits", "Grenzen", "limits"),
        TABLE([("What", "Was"), ("Limit", "Grenze")], [
            [("Message", "Nachricht"), ("500 characters, text only; line breaks become spaces", "500 Zeichen, nur Text; Zeilenumbrüche werden zu Leerzeichen")],
            [("Name, position", "Name, Position"), ("24 characters each", "je 24 Zeichen")],
            [("Messages per participant", "Nachrichten je Teilnehmer"), ("10 in 10 seconds, more are dropped", "10 in 10 Sekunden, weitere fallen weg")],
            [("EMERGENCY per participant", "EMERGENCY je Teilnehmer"), ("3 in a minute with a pop-up; more arrive as normal messages", "3 pro Minute mit Popup; weitere kommen als normale Nachricht an")],
            [("Open EMERGENCY pop-ups", "Offene EMERGENCY-Popups"), ("20 at most; more arrive as normal messages", "höchstens 20; weitere kommen als normale Nachricht an")],
            [("Kept", "Behalten"), ("the last 200 messages, only in memory; they are gone when the chat is switched off or LJ Link quits", "die letzten 200 Nachrichten, nur im Speicher; beim Abschalten des Chats oder Beenden von LJ Link sind sie weg")],
        ]),
        H2("Privacy", "Datenschutz", "privacy"),
        UL(("**Every device in the same network can read along, and anyone there with a suite program can write.** Nothing is encrypted. Do not write anything you would not say out loud in the booth.",
            "**Jedes Gerät im selben Netzwerk kann mitlesen, und jeder dort mit einem Suite-Programm kann schreiben.** Nichts ist verschlüsselt. Nichts schreiben, was du in der Booth nicht laut sagen würdest."),
           ("**Nothing leaves the local network:** the chat uses multicast with a time to live of 1, so routers do not pass it on. No internet, no cloud.",
            "**Nichts verlässt das lokale Netzwerk:** Der Chat nutzt Multicast mit einer Lebensdauer (TTL) von 1, Router geben ihn also nicht weiter. Kein Internet, keine Cloud."),
           ("**Chat texts are never written to a log, a file or a problem report.** A report only says whether the chat is on and how many messages are in memory, other programs are in the room and emergencies are open, never texts or names. LJ Link keeps your name, position and the on/off setting in its settings.",
            "**Chat-Texte kommen nie in ein Log, eine Datei oder einen Problembericht.** Ein Bericht sagt nur, ob der Chat an ist und wie viele Nachrichten im Speicher, andere Programme im Raum und Notfälle offen sind, nie Texte oder Namen. Name, Position und die Ein/Aus-Einstellung speichert LJ Link in seinen Einstellungen.")),
        H2("Network and firewall", "Netzwerk und Firewall", "network"),
        TABLE([("What", "Was"), ("Details", "Details")], [
            [("Transport", "Übertragung"), ("UDP multicast, group `239.255.76.76`, port **47676**, TTL 1, on every network adapter", "UDP-Multicast, Gruppe `239.255.76.76`, Port **47676**, TTL 1, auf jedem Netzwerkadapter")],
            [("Guest Wi-Fi with client isolation", "Gäste-WLAN mit Client-Isolation"), ("blocks the devices from each other: **no chat** there", "trennt die Geräte voneinander: dort **kein Chat**")],
            [("macOS", "macOS"), ("asks for **Local Network** the first time; allow it", "fragt beim ersten Mal nach **Lokales Netzwerk**; erlauben")],
            [("Windows", "Windows"), ("the firewall may ask for UDP 47676; allow **private networks** (not tested on Windows yet)", "die Firewall fragt eventuell nach UDP 47676; **private Netzwerke** erlauben (unter Windows noch nicht getestet)")],
        ]),
        P("Nobody shows up? See [troubleshooting](wiki-troubleshooting.html#chat).", "Niemand erscheint? Siehe [Fehlersuche](wiki-troubleshooting.html#chat)."),
    )
    return (("Suite chat (alpha)", "Suite-Chat (Alpha)"),
            ("The suite chat in LJ Link: one chat room for the suite programs in the same network, without a server. Name and position, EMERGENCY pop-up, unread messages, switching it off, limits, privacy and firewall.",
             "Der Suite-Chat in LJ Link: ein Chatraum für die Suite-Programme im selben Netzwerk, ohne Server. Name und Position, EMERGENCY-Popup, ungelesene Nachrichten, Abschalten, Grenzen, Datenschutz und Firewall."),
            ("Start", "Start"), ("Suite chat", "Suite-Chat"),
            ("Booth, FOH and VJ write to each other across the floor, with an EMERGENCY button for when it matters. Alpha.", "Booth, FOH und VJ schreiben sich quer über die Tanzfläche, mit einem EMERGENCY-Knopf für den Ernstfall. Alpha."), body)
